@addTagHelper *, Microsoft.AspNetCore.Mvc.TagHelpers

// For a specific assembly:
@addTagHelper "*, MyApp"

// To remove a tag helper:
@removeTagHelper *, Microsoft.AspNetCore.Mvc.TagHelpers

[HtmlTargetElement("auto-bold")]
public class AutoBoldTagHelper : TagHelper
{
    public override async Task ProcessAsync(TagHelperContext context, TagHelperOutput output)
    {
        output.TagName = "strong";
        output.Attributes.SetAttribute("class", "text-primary");
        var child = await output.GetChildContentAsync();
        output.Content.SetHtmlContent(child);
    }
}

// Usage in a view:
<auto-bold>This text becomes bold.</auto-bold>

<!-- Renders as: -->
<strong class="text-primary">This text becomes bold.</strong>
